function snapshot_ToyChart()
% Self-contained snapshot generated by simulink-snapshot-edit.
% Run once to rebuild ToyChart.slx exactly (blocks/params/positions/routing).
% Local-edit workflow: edit only the lines of the block you need.
  if bdIsLoaded('ToyChart'), close_system('ToyChart', 0); end
  new_system('ToyChart');
  m = 'ToyChart';

  % ---- solver / config / model params ----

  % ---- callbacks ----

  % ---- Model Workspace variables ----

  % ---- blocks (positions & full parameters preserved) ----
  add_block('sflib/Chart', [m '/c1'], 'Position', [100 100 300 260], 'ShowPortLabels', 'FromPortIcon', 'SystemSampleTime', '-1');
  % ---- chart c1 内容（Stateflow 结构化导出）----
  chc1_rt = sfroot();
  chc1_ch = chc1_rt.find('-isa', 'Stateflow.Chart', '-and', 'Path', [m '/c1']); chc1_ch = chc1_ch(1);
  chc1_s1 = Stateflow.State(chc1_ch); chc1_s1.Name = 'On'; chc1_s1.LabelString = sprintf('On');
  chc1_s2 = Stateflow.State(chc1_ch); chc1_s2.Name = 'Off'; chc1_s2.LabelString = sprintf('Off');
  chc1_t1 = Stateflow.Transition(chc1_ch); chc1_t1.Source = chc1_s1; chc1_t1.Destination = chc1_s2; chc1_t1.LabelString = sprintf('timeout');
  % ---- chart c1 end ----
  try, set_param(m, 'SimulationCommand', 'update'); catch, end

  % ---- lines ----

  % ---- annotations (top level) ----

  snpDir = fileparts(mfilename('fullpath'));
  snpOut = fullfile(snpDir, '..\models');
  try, bdclose('ToyChart_tmp_save'); catch, end
  if ~isfolder(snpOut), mkdir(snpOut); end
  if isfile(fullfile(snpOut, 'ToyChart_tmp_save.slx')), delete(fullfile(snpOut, 'ToyChart_tmp_save.slx')); end
  save_system(m, fullfile(snpOut, 'ToyChart_tmp_save.slx'));
  close_system(m, 0);
  movefile(fullfile(snpOut, 'ToyChart_tmp_save.slx'), fullfile(snpOut, 'ToyChart.slx'), 'f');
end

